import{_ as l,a0 as i,w as p,s as u,I as n,x as e,a1 as o,A as r,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"开源 vs. 闭源 | LCTT x X-CMD","titleTemplate":false,"description":"开源 vs. 闭源 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源 vs. 闭源 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源 vs. 闭源 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161104 Open Source Vs Closed Source","title":"开源 vs. 闭源","tag":"201611","desc":""},"relativePath":"201611/20161104 Open Source Vs Closed Source.md","filePath":"[post].md"}'),d={name:"201611/20161104 Open Source Vs Closed Source.md"};function m(h,t,f,x,b,g){const a=i("Link");return p(),u("div",null,[t[18]||(t[18]=n("h1",{id:"开源-vs-闭源",tabindex:"-1"},[e("开源 vs. 闭源 "),n("a",{class:"header-anchor",href:"#开源-vs-闭源","aria-label":"Permalink to “开源 vs. 闭源”"},"​")],-1)),n("p",null,[o(a,{href:"http://www.linuxandubuntu.com/home/open-source-vs-closed-source"},{default:r(()=>[...t[0]||(t[0]=[n("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/open-source-vs-closed-source_orig.jpg",alt:"开源 vs. 闭源"},null,-1)])]),_:1})]),t[19]||(t[19]=n("p",null,[n("strong",null,"开源操作系统"),e("和"),n("strong",null,"闭源操作系统"),e("之间有诸多不同。这里我们仅寥书几笔。")],-1)),t[20]||(t[20]=n("h3",{id:"开源是什么-自由",tabindex:"-1"},[e("开源是什么？自由！ "),n("a",{class:"header-anchor",href:"#开源是什么-自由","aria-label":"Permalink to “开源是什么？自由！”"},"​")],-1)),n("p",null,[o(a,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/what-is-open-source_orig.jpg?250"},{default:r(()=>[...t[1]||(t[1]=[n("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/what-is-open-source.jpg?250",alt:"开源是什么？"},null,-1)])]),_:1})]),t[21]||(t[21]=s('<p>这是用户需要知道的最重要的一点。无论我是否打算修改代码，其他人出于善意的修改都不应受到限制。且如果用户喜欢，他们可以分享这个软件。使用<strong>开源</strong>软件，这些都是可能的。</p><p><strong>闭源</strong>操作系统的许可条款很是吓人。但真的所有人都会看吗？不，许多用户只是点了一下‘Accept’ 而已。</p><h3 id="价格" tabindex="-1">价格 <a class="header-anchor" href="#价格" aria-label="Permalink to “价格”">​</a></h3><p>几乎所有的开源操纵系统是免费的。仅有自愿性质的捐款。且只需有个一个 <strong>CD/DVD 或 USB</strong> 就能将系统安装到所有你想要安装的电脑上。</p><p>闭源操作系统相较于开源 OS 就贵了许多，如果你用它来构建 PC，每台 PC 得你花不少于 $100。</p><p>我们可以用花在闭源软件上的钱去买更好的东西。</p><h3 id="选择" tabindex="-1">选择 <a class="header-anchor" href="#选择" aria-label="Permalink to “选择”">​</a></h3><p>开源操作系统的发行版有很多。如果你不中意眼下的这个，你可以尝试其他的发行版，总能找到适合你的那一个。</p><p>诸如 Ubuntu studio、Bio Linux、Edubuntu、Kali Linux、Qubes、SteamOS 这些发行版，就是针对特定用户群产生的发行版。</p><p>闭源软件有“选择”这种说法吗？我觉得是没有的。</p><h3 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to “隐私”">​</a></h3><p><strong>开源操作系统</strong>无需收集用户数据信息。不会根据用户的个性显示广告，也不会把你的信息卖给第三方机构。如果开发者需要资金，他们会要求捐助，或是在他们的网页上打广告。广告的内容也会与 Linux 相关，对我们有益无害。</p><p>你一定知道那个主流的闭源操作系统（名字就不写了，大家都知道的），据说因为收集用户信息这件事，导致多数用户关闭了他们的免费更新服务。多数该系统的用户为了避免升级，将更新功能关闭，他们宁可承担安全风险也不要免费更新。</p><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><p>开源软件大多安全。究其缘由不仅有市场占有率低这个原因，其本身的构成方式就比较安全。例如， Qubes Os 是最安全的操作系统之一，它将运行的软件相互隔离。</p><p>闭源操作系统向易用性妥协，使其变得愈发脆弱。</p><h3 id="硬件支持" tabindex="-1">硬件支持 <a class="header-anchor" href="#硬件支持" aria-label="Permalink to “硬件支持”">​</a></h3>',17)),n("p",null,[t[3]||(t[3]=e("我们中有大多数人，家里还放着那些不想丢的旧 PC，这时一个轻量级的发行版可能会让这些老家伙们重获新生。你可以试试在文章 ",-1)),o(a,{href:"http://www.linuxandubuntu.com/home/5-lightweight-linux-for-old-computers"},{default:r(()=>[...t[2]||(t[2]=[e("5 个适合旧电脑的轻量级 Linux",-1)])]),_:1}),t[4]||(t[4]=e(" 中罗列的那些轻量级操作系统发行版。基于 Linux 的系统几乎包含所有设备的驱动，所以基本不需要你亲自寻找、安装驱动。",-1))]),t[22]||(t[22]=s('<p>闭源操作系统时不时中止对旧硬件的支持，迫使用户去购买新的硬件。我们还不得不亲自寻找、安装驱动。</p><h3 id="社区支持" tabindex="-1">社区支持 <a class="header-anchor" href="#社区支持" aria-label="Permalink to “社区支持”">​</a></h3><p>几乎所有的<strong>开源操作系统</strong>都有用户论坛，你可以在那里提问题，并从别的用户那里得到答案。大家在那里分享技巧和窍门，互帮互助。有经验的 Linux 用户往往乐于帮助新手，为此他们常常不遗余力。</p><p><strong>闭源操作系统</strong>社区和开源操作系统社区简直无法相提并论。提出的问题常常得不到回答。</p><h3 id="商业化" tabindex="-1">商业化 <a class="header-anchor" href="#商业化" aria-label="Permalink to “商业化”">​</a></h3><p>在操作系统上挣钱是非常困难的。（开源）开发者一般通过用户的捐款和在网站上打广告来挣钱。捐款主要用于支付主机的开销和开发者的薪水。</p><p>许多闭源操作系统，不仅仅通过出售软件的使用许可这种方式来赚钱，还会推送广告大赚一票。</p><h3 id="垃圾应用" tabindex="-1">垃圾应用 <a class="header-anchor" href="#垃圾应用" aria-label="Permalink to “垃圾应用”">​</a></h3><p>我承认有些开源操作系统会提供一些我们可能一辈子都不会用到的应用，有些人认为他们是垃圾应用。但是也有发行版只提供最小安装，其中就不包含这些不想要的软件。所以，这不是真正的问题。</p><p>而所有的闭源操作系统中都包含厂商安装的垃圾应用，强制你安装，就像在安装一个干净系统一样。</p><p>开源软件更像是一门哲学。一种分享和学习的方式。甚至还有益于经济。</p><p>我们已经将我们知晓的罗列了出来。如果你觉得我们还漏了些什么，可以评论告诉我们。</p><hr>',13)),n("p",null,[t[6]||(t[6]=e("via: ",-1)),o(a,{href:"http://www.linuxandubuntu.com/home/open-source-vs-closed-source"},{default:r(()=>[...t[5]||(t[5]=[e("http://www.linuxandubuntu.com/home/open-source-vs-closed-source",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=e("作者：",-1)),o(a,{href:"https://www.linkedin.com/in/mohdsohail"},{default:r(()=>[...t[7]||(t[7]=[e("Mohd Sohail",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),o(a,{href:"https://github.com/martin2011qi"},{default:r(()=>[...t[8]||(t[8]=[e("martin2011qi",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),o(a,{href:"https://github.com/jasminepeng"},{default:r(()=>[...t[9]||(t[9]=[e("jasminepeng",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),o(a,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const S=l(d,[["render",m]]);export{C as __pageData,S as default};
